from decimal import Decimal, InvalidOperation


class InsufficientFunds(Exception):
    pass


class Ledger:
    _PATTERN = Decimal("1.00")
    _FEE = Decimal("1.50")

    def __init__(self, overdraft_limit: str = "0.00"):
        self._overdraft_limit = self._validate(overdraft_limit, allow_zero=True)
        self._balance = Decimal("0.00")
        self._history = []

    def _validate(self, amount: str, allow_zero: bool = False) -> Decimal:
        if not isinstance(amount, str):
            raise TypeError("amount must be a string")
        if not amount:
            raise ValueError("invalid amount format")

        if "." in amount:
            whole, frac = amount.split(".", 1)
            if not frac or len(frac) > 2 or not frac.isdigit():
                raise ValueError("invalid amount format")
        else:
            whole = amount
            frac = ""

        if not whole.isdigit() or not whole:
            raise ValueError("invalid amount format")

        try:
            value = Decimal(amount)
        except InvalidOperation:
            raise ValueError("invalid amount format")

        if not allow_zero and value == 0:
            raise ValueError("amount must be positive")

        return value

    def deposit(self, amount: str):
        value = self._validate(amount)
        self._balance += value
        self._history.append(("deposit", str(value.quantize(self._PATTERN))))

    def withdraw(self, amount: str):
        value = self._validate(amount)
        post_balance = self._balance - value

        if post_balance < -self._overdraft_limit:
            raise InsufficientFunds("withdrawal would exceed overdraft limit")

        self._balance = post_balance
        self._history.append(("withdraw", str(value.quantize(self._PATTERN))))

        if self._balance < 0:
            self._balance -= self._FEE
            self._history.append(("fee", str(self._FEE.quantize(self._PATTERN))))

    def balance(self) -> str:
        return str(self._balance.quantize(self._PATTERN))

    def history(self) -> list[tuple[str, str]]:
        return list(self._history)
