def parse_ini(text: str) -> dict:
    result: dict = {}
    current_section: str = ""
    current_key: str | None = None

    lines = text.split("\n")
    for line_no, raw_line in enumerate(lines, start=1):
        line = raw_line.removesuffix("\r")

        # Rule 1: blank or whitespace-only line
        if line.strip() == "":
            current_key = None
            continue

        # Rule 2: comment line (first non-whitespace is ';' or '#')
        stripped_left = line.lstrip()
        if stripped_left[0] in ";#":
            continue

        # Rule 3: continuation line (starts with space or tab)
        if line[0] in " \t":
            if current_key is None:
                raise ValueError(f"line {line_no}: continuation without active key")
            continuation_text = line.strip()
            old_value = result[current_section][current_key]
            if old_value == "":
                result[current_section][current_key] = continuation_text
            else:
                result[current_section][current_key] = old_value + " " + continuation_text
            continue

        # Rule 4: section header
        stripped = line.strip()
        if stripped.startswith("[") and stripped.endswith("]") and "\n" not in stripped:
            section_name = stripped[1:-1].strip().lower()
            current_section = section_name
            current_key = None
            continue

        # Rule 5: key-value line
        if "=" not in line:
            raise ValueError(f"line {line_no}: missing '='")
        key_part, value_part = line.split("=", 1)
        key = key_part.strip().lower()
        value = value_part.strip()
        if key == "":
            raise ValueError(f"line {line_no}: empty key")
        if current_section not in result:
            result[current_section] = {}
        if key in result[current_section]:
            raise ValueError(f"duplicate key '{key}' in section '{current_section}'")
        result[current_section][key] = value
        current_key = key

    # Rule 6: remove one pair of surrounding quotes from values
    for section in result.values():
        for k, v in section.items():
            if len(v) >= 2 and v.startswith('"') and v.endswith('"'):
                section[k] = v[1:-1]

    return result
