def render(template: str, values: dict) -> str:
    import re
    output = []
    i = 0
    n = len(template)
    key_regex = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')
    while i < n:
        ch = template[i]
        if ch == '\\':
            if i + 1 < n and template[i + 1] == '\\':
                output.append('\\')
                i += 2
            elif i + 2 < n and template[i + 1] == '{' and template[i + 2] == '{':
                output.append('{{')
                i += 3
            else:
                output.append('\\')
                i += 1
        elif ch == '{' and i + 1 < n and template[i + 1] == '{':
            end = template.find('}}', i + 2)
            if end == -1:
                raise ValueError(f'unclosed placeholder at {i}')
            content = template[i + 2:end]
            pipe_pos = content.find('|')
            if pipe_pos == -1:
                key_part = content
                default = None
            else:
                key_part = content[:pipe_pos]
                default = content[pipe_pos + 1:]
            stripped_key = key_part.strip(' ')
            stripped_default = default.strip(' ') if default is not None else None
            if not stripped_key:
                raise ValueError(f'bad key: {stripped_key}')
            parts = stripped_key.split('.')
            for part in parts:
                if not key_regex.match(part):
                    raise ValueError(f'bad key: {stripped_key}')
            current = values
            missing = False
            for part in parts:
                if not isinstance(current, dict) or part not in current:
                    missing = True
                    break
                current = current[part]
            if not missing and current is None:
                missing = True
            if missing:
                if stripped_default is not None:
                    output.append(stripped_default)
                else:
                    raise KeyError(f'missing: {stripped_key}')
            else:
                if current is True:
                    output.append('true')
                elif current is False:
                    output.append('false')
                else:
                    output.append(str(current))
            i = end + 2
        else:
            output.append(ch)
            i += 1
    return ''.join(output)
