import heapq


class CycleError(ValueError):
    def __init__(self, nodes):
        self.nodes = sorted(nodes)
        super().__init__(f"cycle detected involving nodes: {self.nodes}")


def _build_graph(nodes, edges):
    node_set = set(nodes)
    for before, after in edges:
        if before not in node_set:
            raise ValueError(f"unknown node: {before}")
        if after not in node_set:
            raise ValueError(f"unknown node: {after}")

    unique_edges = []
    seen_edges = set()
    for edge in edges:
        key = (edge[0], edge[1])
        if key not in seen_edges:
            seen_edges.add(key)
            unique_edges.append(edge)

    adjacency = {node: [] for node in node_set}
    indegree = {node: 0 for node in node_set}
    for before, after in unique_edges:
        adjacency[before].append(after)
        indegree[after] += 1

    return node_set, adjacency, indegree


def topo_order(nodes, edges):
    node_set, adjacency, indegree = _build_graph(nodes, edges)

    heap = [node for node in node_set if indegree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        current = heapq.heappop(heap)
        result.append(current)
        for neighbor in adjacency[current]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(node_set):
        remaining = [node for node in node_set if node not in result]
        raise CycleError(remaining)

    return result


def layers(nodes, edges):
    node_set, adjacency, indegree = _build_graph(nodes, edges)

    remaining = set(node_set)
    result = []
    while remaining:
        layer = [node for node in remaining if indegree[node] == 0]
        if not layer:
            raise CycleError(remaining)
        layer.sort()
        result.append(layer)
        for node in layer:
            remaining.remove(node)
            for neighbor in adjacency[node]:
                indegree[neighbor] -= 1

    return result
