def _validate(prices):
    if not isinstance(prices, list):
        raise TypeError("prices must be a list")
    for p in prices:
        if p is None:
            continue
        if isinstance(p, bool) or not isinstance(p, (int, float)):
            raise TypeError("prices elements must be int, float, or None")


def spans(prices):
    _validate(prices)
    result = [0] * len(prices)
    stack = []
    last_none = -1
    for i, p in enumerate(prices):
        if p is None:
            last_none = i
            stack.clear()
            continue
        while stack and prices[stack[-1]] > p:
            stack.pop()
        top = stack[-1] if stack else last_none
        result[i] = i - top
        stack.append(i)
    return result


def next_greater(prices):
    _validate(prices)
    result = [-1] * len(prices)
    stack = []
    for i in range(len(prices) - 1, -1, -1):
        p = prices[i]
        if p is None:
            stack.clear()
            continue
        while stack and prices[stack[-1]] <= p:
            stack.pop()
        result[i] = stack[-1] if stack else -1
        stack.append(i)
    return result


def widest_span(prices):
    _validate(prices)
    span_values = spans(prices)
    best_idx = -1
    best_span = 0
    for i, s in enumerate(span_values):
        if s >= best_span:
            best_idx = i
            best_span = s
    return (best_idx, best_span)
