import collections
import re
from decimal import Decimal, ROUND_HALF_EVEN

_PRICE_RE = re.compile(r'^[0-9]+(?:\.[0-9]{1,4})?$')
_ZERO = Decimal('0.00')
_ONE_CENT = Decimal('0.01')


class FifoBook:
    def __init__(self) -> None:
        # Each lot: (remaining_qty, original_price_str, buy_decimal)
        self._lots: collections.deque[tuple[int, str, Decimal]] = collections.deque()
        self._realized: list[Decimal] = []

    @staticmethod
    def _validate_qty(qty: int) -> int:
        if type(qty) is not int:
            raise TypeError('qty must be an int')
        if qty <= 0:
            raise ValueError('qty must be positive')
        return qty

    @staticmethod
    def _validate_price(price: str) -> Decimal:
        if type(price) is not str:
            raise TypeError('price must be a str')
        if not _PRICE_RE.match(price):
            raise ValueError('invalid price string')
        return Decimal(price)

    def buy(self, qty: int, price: str) -> None:
        qty = self._validate_qty(qty)
        buy_decimal = self._validate_price(price)
        self._lots.append((qty, price, buy_decimal))

    def sell(self, qty: int, price: str) -> Decimal:
        qty = self._validate_qty(qty)
        sell_decimal = self._validate_price(price)

        if qty > self.holdings():
            raise ValueError('insufficient holdings')

        total = Decimal(0)
        remaining = qty

        while remaining > 0:
            front_qty, front_price, front_decimal = self._lots[0]
            portion = front_qty if front_qty <= remaining else remaining
            total += (sell_decimal - front_decimal) * portion
            if front_qty <= remaining:
                self._lots.popleft()
            else:
                self._lots[0] = (front_qty - portion, front_price, front_decimal)
            remaining -= portion

        quantized = total.quantize(_ONE_CENT, rounding=ROUND_HALF_EVEN)
        self._realized.append(quantized)
        return quantized

    def realized(self) -> Decimal:
        if not self._realized:
            return _ZERO
        return sum(self._realized, Decimal(0)).quantize(_ONE_CENT, rounding=ROUND_HALF_EVEN)

    def holdings(self) -> int:
        return sum(lot[0] for lot in self._lots)

    def lots(self) -> list[tuple[int, str]]:
        return [(lot[0], lot[1]) for lot in self._lots]

    def cost_basis(self) -> Decimal:
        total = sum(lot[0] * lot[2] for lot in self._lots)
        return total.quantize(_ONE_CENT, rounding=ROUND_HALF_EVEN)
