import re

_VERSION_RE = re.compile(
    r"""
    (?i)                       # case-insensitive for leading v/V
    ^                          # anchored at start
    [vV]?                      # optional single leading v or V
    (?P<major>0|[1-9]\d*)      # major: no leading zeros
    \.
    (?P<minor>0|[1-9]\d*)      # minor: no leading zeros
    \.
    (?P<patch>0|[1-9]\d*)      # patch: no leading zeros
    (?:                        # optional prerelease
        -
        (?P<prerelease>[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*)
    )?
    (?:                        # optional build
        \+
        (?P<build>[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*)
    )?
    $                          # anchored at end
    """,
    re.VERBOSE,
)


def _parse_identifier(ident: str) -> int | str:
    if ident.isdigit():
        if len(ident) > 1 and ident[0] == "0":
            raise ValueError("invalid version: numeric prerelease identifier has leading zero")
        return int(ident)
    return ident


def parse_version(text: str) -> tuple[int, int, int, tuple, str | None]:
    match = _VERSION_RE.match(text)
    if not match:
        raise ValueError("invalid version")

    major = int(match.group("major"))
    minor = int(match.group("minor"))
    patch = int(match.group("patch"))

    prerelease_raw = match.group("prerelease")
    if prerelease_raw is None:
        prerelease: tuple = ()
    else:
        try:
            prerelease = tuple(_parse_identifier(ident) for ident in prerelease_raw.split("."))
        except ValueError:
            raise ValueError("invalid version")

    build = match.group("build")
    if build is not None:
        build = str(build)

    return (major, minor, patch, prerelease, build)


def _compare_prerelease(a: tuple, b: tuple) -> int:
    # absent prerelease > present prerelease
    if not a and not b:
        return 0
    if not a:
        return 1
    if not b:
        return -1

    for ident_a, ident_b in zip(a, b):
        a_num = isinstance(ident_a, int)
        b_num = isinstance(ident_b, int)

        if a_num and b_num:
            if ident_a < ident_b:
                return -1
            if ident_a > ident_b:
                return 1
        elif a_num:
            return -1
        elif b_num:
            return 1
        else:
            if ident_a < ident_b:
                return -1
            if ident_a > ident_b:
                return 1

    # all shared identifiers equal: longer list wins (ranks higher)
    if len(a) < len(b):
        return -1
    if len(a) > len(b):
        return 1
    return 0


def compare_versions(a: str, b: str) -> int:
    parsed_a = parse_version(a)
    parsed_b = parse_version(b)

    # compare major, minor, patch numerically
    for field_a, field_b in zip(parsed_a[:3], parsed_b[:3]):
        if field_a < field_b:
            return -1
        if field_a > field_b:
            return 1

    # compare prereleases
    cmp = _compare_prerelease(parsed_a[3], parsed_b[3])
    if cmp != 0:
        return cmp

    # build metadata ignored in comparison
    return 0


def sort_versions(versions: list[str]) -> list[str]:
    # validate all entries first
    for v in versions:
        parse_version(v)

    return sorted(versions, key=lambda v: (parse_version(v)[:4], 0), cmp=None)
