import heapq
from collections.abc import Sequence


def _validate(k, meetings):
    if not isinstance(k, int) or isinstance(k, bool):
        raise ValueError("k must be int and not bool")
    if k < 1:
        raise ValueError("k must be >= 1")

    for mtg in meetings:
        if not isinstance(mtg, Sequence) or len(mtg) != 2:
            raise ValueError("each meeting must be a length-2 sequence")
        start, end = mtg
        if isinstance(start, bool) or isinstance(end, bool):
            raise ValueError("start and end must be int, not bool")
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError("start and end must be int")
        if start >= end:
            raise ValueError("start must be less than end")


def assign_rooms(meetings: list[tuple[int, int]], k: int) -> list[tuple[int, int, int]]:
    _validate(k, meetings)

    n = len(meetings)
    if n == 0:
        return []

    order = sorted(range(n), key=lambda i: (meetings[i][0], i))

    available = list(range(k))
    heapq.heapify(available)
    occupied = []  # min-heap of (release_time, room_id)
    records = [None] * n

    for idx in order:
        start, end = meetings[idx]
        duration = end - start

        while occupied and occupied[0][0] <= start:
            release_time, room_id = heapq.heappop(occupied)
            heapq.heappush(available, room_id)

        if available:
            room_id = heapq.heappop(available)
            actual_start = start
        else:
            release_time, room_id = heapq.heappop(occupied)
            actual_start = release_time

        actual_end = actual_start + duration
        records[idx] = (room_id, actual_start, actual_end)
        heapq.heappush(occupied, (actual_end, room_id))

    return records


def busiest_room(meetings: list[tuple[int, int]], k: int) -> int:
    _validate(k, meetings)

    if not meetings:
        return 0

    records = assign_rooms(meetings, k)
    counts = {}
    for room_id, _, _ in records:
        counts[room_id] = counts.get(room_id, 0) + 1

    max_count = -1
    best_room = 0
    for room_id in range(k):
        cnt = counts.get(room_id, 0)
        if cnt > max_count:
            max_count = cnt
            best_room = room_id

    return best_room
