from typing import Callable, Any


class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock: Callable[[], float]):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        if ttl <= 0:
            raise ValueError("ttl must be > 0")

        self._capacity = capacity
        self._ttl = ttl
        self._clock = clock
        self._cache: OrderedDict[Any, tuple[Any, float]] = OrderedDict()

    def _now(self) -> float:
        return self._clock()

    def _is_expired(self, timestamp: float) -> bool:
        return self._now() - timestamp >= self._ttl

    def get(self, key: Any, default: Any = None) -> Any:
        now = self._now()
        if key not in self._cache:
            return default

        value, timestamp = self._cache[key]
        if self._is_expired(timestamp):
            del self._cache[key]
            return default

        self._cache.move_to_end(key)
        return value

    def put(self, key: Any, value: Any) -> None:
        now = self._now()

        if key in self._cache:
            self._cache[key] = (value, now)
            self._cache.move_to_end(key)
            return

        self._cache[key] = (value, now)
        self._cache.move_to_end(key)

        if len(self._cache) > self._capacity:
            self._purge_expired()
            while len(self._cache) > self._capacity:
                self._cache.popitem(last=False)

    def _purge_expired(self) -> None:
        expired_keys = [key for key, (_, timestamp) in self._cache.items()
                        if self._is_expired(timestamp)]
        for key in expired_keys:
            del self._cache[key]

    def __len__(self) -> int:
        self._purge_expired()
        return len(self._cache)
