def _normalize(intervals):
    result = []
    for item in intervals:
        start, end = item
        if start > end:
            raise ValueError(f"Invalid interval: start {start} > end {end}")
        if start == end:
            continue
        result.append((start, end))
    return result


def merge(intervals):
    normalized = _normalize(intervals)
    if not normalized:
        return []
    normalized.sort(key=lambda x: x[0])
    merged = [normalized[0]]
    for current in normalized[1:]:
        prev_start, prev_end = merged[-1]
        cur_start, cur_end = current
        if cur_start <= prev_end:
            if cur_end > prev_end:
                merged[-1] = (prev_start, cur_end)
        else:
            merged.append(current)
    return merged


def subtract(a, b):
    a_merged = merge(a)
    b_merged = merge(b)
    result = []
    b_index = 0
    for a_start, a_end in a_merged:
        current_start = a_start
        current_end = a_end
        while b_index < len(b_merged) and b_merged[b_index][1] <= current_start:
            b_index += 1
        inner_index = b_index
        while inner_index < len(b_merged) and b_merged[inner_index][0] < current_end:
            b_start, b_end = b_merged[inner_index]
            if b_start > current_start:
                result.append((current_start, b_start))
            current_start = max(current_start, b_end)
            if current_start >= current_end:
                break
            inner_index += 1
        if current_start < current_end:
            result.append((current_start, current_end))
    return result


def total_length(intervals):
    merged = merge(intervals)
    total = 0
    for start, end in merged:
        total += end - start
    return total
