def validate_stream(events) -> None:
    """
    Validate a stream of (timestamp, event_id, payload) tuples.

    Raises:
        ValueError: If any event_id is repeated (message starts 'duplicate id'),
            or if the stream is not strictly increasing by (timestamp, event_id)
            (message starts 'unsorted').
    """
    seen_ids = set()
    for event in events:
        event_id = event[1]
        if event_id in seen_ids:
            raise ValueError(f"duplicate id: {event_id}")
        seen_ids.add(event_id)

    prev = None
    for event in events:
        key = (event[0], event[1])
        if prev is not None and key <= prev:
            raise ValueError(f"unsorted: {event[1]}")
        prev = key


def diff_events(old, new) -> dict:
    """
    Compare two streams and report added, removed, moved, and changed events.

    Returns:
        dict with keys 'added', 'removed', 'moved', 'changed'.
    """
    validate_stream(old)
    validate_stream(new)

    old_map = {}
    for event in old:
        old_map[event[1]] = event

    new_map = {}
    for event in new:
        new_map[event[1]] = event

    added = []
    removed = []
    moved = []
    changed = []

    for event in new:
        event_id = event[1]
        if event_id not in old_map:
            added.append(event_id)
        else:
            old_event = old_map[event_id]
            if event[0] != old_event[0]:
                moved.append(event_id)
            if event[2] != old_event[2]:
                changed.append(event_id)

    for event in old:
        event_id = event[1]
        if event_id not in new_map:
            removed.append(event_id)

    return {
        "added": added,
        "removed": removed,
        "moved": moved,
        "changed": changed,
    }


def merge_streams(a, b) -> list:
    """
    Merge two streams into one valid stream.

    If an event_id is present in both streams, the event from b is kept.
    The result is sorted by (timestamp, event_id).

    Returns:
        A new list containing the merged, sorted stream.
    """
    validate_stream(a)
    validate_stream(b)

    merged = {}
    for event in a:
        merged[event[1]] = event
    for event in b:
        merged[event[1]] = event

    return sorted(merged.values(), key=lambda event: (event[0], event[1]))
