import copy


def _decode_token(token: str) -> str:
    """Decode a single JSON Pointer reference token in one left-to-right pass."""
    result = []
    i = 0
    while i < len(token):
        ch = token[i]
        if ch == '~':
            if i + 1 >= len(token):
                raise ValueError("Invalid escape: '~' at end of token")
            nxt = token[i + 1]
            if nxt == '0':
                result.append('~')
                i += 2
            elif nxt == '1':
                result.append('/')
                i += 2
            else:
                raise ValueError(f"Invalid escape: '~{nxt}'")
        else:
            result.append(ch)
            i += 1
    return ''.join(result)


def _decode_pointer(pointer: str) -> list[str]:
    """Validate and decode a JSON Pointer into a list of reference tokens."""
    if pointer == '':
        return []
    if not pointer.startswith('/'):
        raise ValueError("Non-empty pointer must start with '/'")

    raw_tokens = pointer[1:].split('/')
    return [_decode_token(token) for token in raw_tokens]


def _is_valid_list_index(token: str) -> bool:
    """Check whether token is a valid non-negative decimal list index."""
    if token == '0':
        return True
    if token == '' or token[0] == '0':
        return False
    return token.isdigit()


def resolve(doc, pointer: str):
    """Resolve a JSON Pointer against a document of plain dicts and lists."""
    tokens = _decode_pointer(pointer)

    current = doc
    for token in tokens:
        if isinstance(current, dict):
            if token not in current:
                raise KeyError(f"Missing key: {token!r}")
            current = current[token]
        elif isinstance(current, list):
            if token == '-':
                raise KeyError("Token '-' cannot be resolved on a list")
            if not _is_valid_list_index(token):
                raise KeyError(f"Invalid list index: {token!r}")
            index = int(token)
            if index >= len(current):
                raise KeyError(f"Index out of range: {index}")
            current = current[index]
        else:
            raise KeyError(f"Cannot step into {type(current).__name__}")

    return current


def set_value(doc, pointer: str, value):
    """Return a new document with the value set at the given JSON Pointer."""
    if pointer == '':
        return value

    tokens = _decode_pointer(pointer)
    new_doc = copy.deepcopy(doc)

    parent = new_doc
    for token in tokens[:-1]:
        if isinstance(parent, dict):
            if token not in parent:
                raise KeyError(f"Missing key: {token!r}")
            parent = parent[token]
        elif isinstance(parent, list):
            if not _is_valid_list_index(token):
                raise KeyError(f"Invalid list index: {token!r}")
            index = int(token)
            if index >= len(parent):
                raise KeyError(f"Index out of range: {index}")
            parent = parent[index]
        else:
            raise KeyError(f"Cannot step into {type(parent).__name__}")

    final_token = tokens[-1]

    if isinstance(parent, dict):
        parent[final_token] = value
    elif isinstance(parent, list):
        if final_token == '-':
            parent.append(value)
        elif _is_valid_list_index(final_token):
            index = int(final_token)
            if index > len(parent):
                raise KeyError(f"Index out of range: {index}")
            if index == len(parent):
                parent.append(value)
            else:
                parent[index] = value
        else:
            raise KeyError(f"Invalid list index: {final_token!r}")
    else:
        raise KeyError(f"Cannot set value in {type(parent).__name__}")

    return new_doc


def escape_token(token: str) -> str:
    """Escape a reference token for use inside a JSON Pointer."""
    return token.replace('~', '~0').replace('/', '~1')
