class Scheduler:
    def __init__(self):
        self._tasks = {}
        self._order = 0

    def add(self, name, priority, after=()):
        if name in self._tasks:
            raise ValueError(f"Task {name!r} already added")
        after_set = set(after)
        for dep in after_set:
            if dep not in self._tasks:
                raise KeyError(f"Dependency {dep!r} not found")
        self._tasks[name] = {
            "priority": priority,
            "order": self._order,
            "after": after_set,
            "state": "pending",
        }
        self._order += 1

    def next(self):
        ready = [
            (name, info)
            for name, info in self._tasks.items()
            if info["state"] == "pending"
            and all(self._tasks[dep]["state"] == "completed" for dep in info["after"])
        ]
        if not ready:
            return None
        name, _ = max(ready, key=lambda item: (item[1]["priority"], -item[1]["order"]))
        self._tasks[name]["state"] = "running"
        return name

    def complete(self, name):
        if name not in self._tasks:
            raise KeyError(f"Task {name!r} not found")
        if self._tasks[name]["state"] != "running":
            raise ValueError(f"Task {name!r} is not running")
        self._tasks[name]["state"] = "completed"

    def remaining(self):
        return sum(1 for info in self._tasks.values() if info["state"] != "completed")
