import bisect


def _validate_intervals(intervals):
    for item in intervals:
        if not isinstance(item, (list, tuple)) or len(item) != 3:
            raise TypeError("Each interval must be a 3-element sequence")
        start, end, weight = item
        if type(start) is not int or type(end) is not int or type(weight) is not int:
            raise TypeError("start, end, and weight must be int")
        if start >= end:
            raise ValueError("start must be less than end")


def best_schedule(intervals: list[tuple[int, int, int]]) -> tuple[int, int]:
    _validate_intervals(intervals)

    if not intervals:
        return (0, 0)

    sorted_intervals = sorted(intervals, key=lambda x: (x[1], x[0]))
    ends = [iv[1] for iv in sorted_intervals]

    dp = [(0, 0)]
    for start, end, weight in sorted_intervals:
        idx = bisect.bisect_right(ends, start) - 1
        prev_weight, prev_count = dp[idx + 1]
        candidate_weight = prev_weight + weight
        candidate_count = prev_count + 1
        current_weight, current_count = dp[-1]
        if candidate_weight > current_weight:
            dp.append((candidate_weight, candidate_count))
        elif candidate_weight == current_weight and candidate_count < current_count:
            dp.append((candidate_weight, candidate_count))
        else:
            dp.append((current_weight, current_count))

    total_weight, count = dp[-1]
    if total_weight <= 0:
        return (0, 0)
    return (total_weight, count)


def max_parallel(intervals: list[tuple[int, int, int]]) -> int:
    _validate_intervals(intervals)

    if not intervals:
        return 0

    events = []
    for start, end, _ in intervals:
        events.append((start, 1))
        events.append((end, -1))

    events.sort(key=lambda x: (x[0], x[1]))

    active = 0
    max_active = 0
    for _, delta in events:
        active += delta
        if active > max_active:
            max_active = active

    return max_active
