def to_roman(n: Any) -> str:
    """Return the canonical Roman numeral for n, 1 <= n <= 3999."""
    if type(n) is not int:
        raise TypeError("n must be an int")
    if n < 1 or n > 3999:
        raise ValueError("n must be between 1 and 3999 inclusive")

    parts = []
    for value, numeral in _ROMAN_MAP:
        while n >= value:
            parts.append(numeral)
            n -= value
    return "".join(parts)


def from_roman(s: Any) -> int:
    """Return the integer value of s if s is a canonical Roman numeral."""
    if type(s) is not str:
        raise TypeError("s must be a str")
    if s == "":
        raise ValueError("empty string is not a Roman numeral")

    total = 0
    i = 0
    n = len(s)
    while i < n:
        # Try subtractive pair first.
        matched = False
        if i + 1 < n:
            pair = s[i:i + 2]
            for value, numeral in _ROMAN_MAP:
                if pair == numeral:
                    total += value
                    i += 2
                    matched = True
                    break
        if not matched:
            single = s[i]
            found = False
            for value, numeral in _ROMAN_MAP:
                if single == numeral:
                    total += value
                    i += 1
                    found = True
                    break
            if not found:
                raise ValueError(f"invalid Roman numeral: {s!r}")

    # Accept only if the parsed value round-trips to the exact input.
    if to_roman(total) != s:
        raise ValueError(f"non-canonical Roman numeral: {s!r}")
    return total


def is_roman(s: Any) -> bool:
