from fractions import Fraction
from typing import Union


def evaluate(expr: str) -> Union[int, Fraction]:
    tokens = _tokenize(expr)
    if not tokens:
        raise ValueError("empty input")
    parser = _Parser(tokens)
    result = parser.parse_expr()
    if parser.pos != len(tokens):
        raise ValueError("leftover tokens")
    if result.denominator == 1:
        return result.numerator
    return result


def _tokenize(expr: str):
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch in " \t":
            i += 1
            continue
        if ch.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(Fraction(int(expr[i:j]), 1))
            i = j
            continue
        if ch in "+-*/^()":
            tokens.append(ch)
            i += 1
            continue
        raise ValueError(f"invalid character: {ch!r}")
    return tokens


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def _peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def _consume(self, expected=None):
        token = self._peek()
        if token is None:
            raise ValueError("unexpected end of input")
        if expected is not None and token != expected:
            raise ValueError(f"expected {expected!r}, got {token!r}")
        self.pos += 1
        return token

    def parse_expr(self):
        value = self.parse_term()
        while True:
            op = self._peek()
            if op == "+" or op == "-":
                self._consume()
                rhs = self.parse_term()
                if op == "+":
                    value = value + rhs
                else:
                    value = value - rhs
            else:
                break
        return value

    def parse_term(self):
        value = self.parse_unary()
        while True:
            op = self._peek()
            if op == "*" or op == "/":
                self._consume()
                rhs = self.parse_unary()
                if op == "*":
                    value = value * rhs
                else:
                    value = value / rhs
            else:
                break
        return value

    def parse_unary(self):
        if self._peek() == "-":
            self._consume()
            value = self.parse_unary()
            return -value
        return self.parse_power()

    def parse_power(self):
        base = self.parse_atom()
        if self._peek() == "^":
            self._consume()
            exponent = self.parse_unary()
            if exponent.denominator != 1:
                raise ValueError("exponent must be a whole number")
            exp_int = exponent.numerator
            if base == 0:
                if exp_int < 0:
                    raise ZeroDivisionError("0 cannot be raised to a negative power")
                if exp_int == 0:
                    return Fraction(1, 1)
                return Fraction(0, 1)
            return _int_pow_fraction(base, exp_int)
        return base

    def parse_atom(self):
        token = self._peek()
        if token is None:
            raise ValueError("expected atom")
        if isinstance(token, Fraction):
            self._consume()
            return token
        if token == "(":
            self._consume()
            value = self.parse_expr()
            if self._peek() != ")":
                raise ValueError("missing closing parenthesis")
            self._consume()
            return value
        raise ValueError(f"unexpected token: {token!r}")


def _int_pow_fraction(base: Fraction, exp: int) -> Fraction:
    if exp < 0:
        if base == 0:
            raise ZeroDivisionError("division by zero in negative exponent")
        base = Fraction(base.denominator, base.numerator)
        exp = -exp
    result = Fraction(1, 1)
    while exp:
        if exp & 1:
            result *= base
        base *= base
        exp >>= 1
    return result
