def _parse(version: str) -> tuple[int, ...]:
    stripped = version.strip()
    if not stripped:
        raise ValueError("empty version")
    parts = stripped.split(".")
    if not parts:
        raise ValueError("empty version")
    nums = []
    for part in parts:
        if not part or not part.isdigit():
            raise ValueError(f"invalid version component: {part!r}")
        nums.append(int(part))
    return tuple(nums)


def _compare(a: tuple[int, ...], b: tuple[int, ...]) -> int:
    length = max(len(a), len(b))
    for i in range(length):
        av = a[i] if i < len(a) else 0
        bv = b[i] if i < len(b) else 0
        if av < bv:
            return -1
        if av > bv:
            return 1
    return 0


def _parse_spec_version(spec_version: str) -> tuple[int, ...]:
    return _parse(spec_version)


def _compatible_release(version: tuple[int, ...], spec_version: tuple[int, ...]) -> bool:
    if len(spec_version) < 2:
        raise ValueError("~= requires multi-component version")
    if not _satisfies_clause(version, ">=", spec_version):
        return False
    base = list(spec_version[:-1])
    base[-1] += 1
    upper = tuple(base)
    return _compare(version, upper) < 0


def _satisfies_clause(version: tuple[int, ...], op: str, spec_version: tuple[int, ...]) -> bool:
    cmp = _compare(version, spec_version)
    if op == "==":
        return cmp == 0
    if op == "!=":
        return cmp != 0
    if op == ">=":
        return cmp >= 0
    if op == "<=":
        return cmp <= 0
    if op == ">":
        return cmp > 0
    if op == "<":
        return cmp < 0
    if op == "~=":
        return _compatible_release(version, spec_version)
    raise ValueError(f"unknown operator: {op!r}")


def satisfies(version: str, spec: str) -> bool:
    v = _parse(version)
    if not spec or not spec.strip():
        return True
    clauses = spec.split(",")
    for clause in clauses:
        stripped_clause = clause.strip()
        if not stripped_clause:
            raise ValueError("empty clause")
        for op in ("==", "!=", ">=", "<=", "~=", ">", "<"):
            if stripped_clause.startswith(op):
                spec_version_str = stripped_clause[len(op):].strip()
                if not spec_version_str:
                    raise ValueError("missing version in clause")
                sv = _parse_spec_version(spec_version_str)
                if not _satisfies_clause(v, op, sv):
                    return False
                break
        else:
            raise ValueError(f"clause without operator: {stripped_clause!r}")
    return True


def max_satisfying(versions: list[str], spec: str) -> str | None:
    parsed_versions = []
    for original in versions:
        parsed_versions.append((_parse(original), original))
    best = None
    best_original = None
    for pv, original in parsed_versions:
        if satisfies(original, spec):
            if best is None or _compare(pv, best) > 0:
                best = pv
                best_original = original
    return best_original
