    if isinstance(x, float) and isnan(x):
        raise ValueError("values must not contain NaN")


def _validate_values(values: list) -> None:
    for x in values:
        _validate_value(x)


def longest_calm(values: list, limit: Union[int, float]) -> tuple[int, int]:
    _validate_limit(limit)

    n = len(values)
    if n == 0:
        return (0, 0)

    _validate_values(values)

    max_deque = deque()  # indices with decreasing values
    min_deque = deque()  # indices with increasing values
    l = 0
    best_len = 0
    best_start = 0

    for r in range(n):
        x = values[r]
        while max_deque and values[max_deque[-1]] <= x:
            max_deque.pop()
        max_deque.append(r)
        while min_deque and values[min_deque[-1]] >= x:
            min_deque.pop()
        min_deque.append(r)

        while (
            max_deque
            and min_deque
            and values[max_deque[0]] - values[min_deque[0]] > limit
        ):
            if max_deque[0] == l:
                max_deque.popleft()
            if min_deque[0] == l:
                min_deque.popleft()
            l += 1

        length = r - l + 1
        if length > best_len:
            best_len = length
            best_start = l

    return (best_start, best_start + best_len)


def count_calm(values: list, limit: Union[int, float]) -> int:
    _validate_limit(limit)

    n = len(values)
    if n == 0:
        return 0

    _validate_values(values)

    max_deque = deque()
    min_deque = deque()
    l = 0
    total = 0

    for r in range(n):
        x = values[r]
        while max_deque and values[max_deque[-1]] <= x:
            max_deque.pop()
        max_deque.append(r)
        while min_deque and values[min_deque[-1]] >= x:
            min_deque.pop()
        min_deque.append(r)

        while (
            max_deque
            and min_deque
            and values[max_deque[0]] - values[min_deque[0]] > limit
        ):
            if max_deque[0] == l:
                max_deque.popleft()
            if min_deque[0] == l:
                min_deque.popleft()
            l += 1

        total += r - l + 1

    return total
